power_user.custom_css:
/* === High Transparency Glassmorphism Light Theme === */
:root {
    --SmartThemeBodyColor: #1e293b !important;
    --SmartThemeEmColor: #334155 !important;
    --SmartThemeUnderlineColor: #2563eb !important;
    --SmartThemeQuoteColor: #d97706 !important;
    --SmartThemeBorderColor: rgba(255, 255, 255, 0.5) !important;
    --SmartThemeShadowColor: rgba(255, 255, 255, 0.8) !important;
}

/* 1. 壁纸背景柔和模糊，烘托层次感 */
#bg1 {
    filter: blur(6px) brightness(0.96) !important;
    transform: scale(1.04) !important; /* 消除模糊边缘白边 */
}

/* 2. 聊天主区域纯透明 */
#chat {
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

/* 3. 消息气泡：纯净通透毛玻璃 */
.mes {
    color: #1e293b !important;
    text-shadow: 0 1px 2px rgba(255, 255, 255, 0.9) !important;
}

body.bubblechat .mes {
    background: rgba(255, 255, 255, 0.32) !important;
    backdrop-filter: blur(12px) saturate(130%) !important;
    -webkit-backdrop-filter: blur(12px) saturate(130%) !important;
    border: 1px solid rgba(255, 255, 255, 0.65) !important;
    border-radius: 16px !important;
    box-shadow: 0 8px 30px rgba(15, 23, 42, 0.06), inset 0 0 0 1px rgba(255, 255, 255, 0.45) !important;
    margin-bottom: 12px !important;
}

/* 用户发言气泡：透亮冰海蓝 */
body.bubblechat .mes[is_user="true"] {
    background: rgba(224, 242, 254, 0.38) !important;
    border-color: rgba(186, 230, 253, 0.75) !important;
}

/* 角色名与正文字体 */
.ch_name {
    color: #0f172a !important;
    font-weight: 700 !important;
    text-shadow: 0 1px 3px rgba(255, 255, 255, 0.95) !important;
}

.mes_text {
    color: #0f172a !important;
    font-size: 1.02rem !important;
    line-height: 1.65 !important;
    font-weight: 500 !important;
}

.mes_text em, .mes_text i {
    color: #334155 !important;
}

.mes_text strong, .mes_text b {
    color: #000000 !important;
    font-weight: 700 !important;
}

/* 4. 顶部栏 (Top Bar) 统一毛玻璃半透明 */
#top-bar {
    background: rgba(255, 255, 255, 0.35) !important;
    backdrop-filter: blur(14px) !important;
    -webkit-backdrop-filter: blur(14px) !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.5) !important;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05) !important;
}

#top-bar h3, #top-bar h4, #top-bar i, #top-bar div {
    color: #1e293b !important;
}

/* 5. 侧边栏抽屉 (Drawers & Settings Panels) 统一浅色半透明 */
.drawer-content {
    background: rgba(255, 255, 255, 0.65) !important;
    backdrop-filter: blur(18px) saturate(140%) !important;
    -webkit-backdrop-filter: blur(18px) saturate(140%) !important;
    border: 1px solid rgba(255, 255, 255, 0.7) !important;
    color: #1e293b !important;
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.12) !important;
}

.drawer-content h3, .drawer-content h4, .drawer-content label, .drawer-content span {
    color: #0f172a !important;
}

.drawer-content input, .drawer-content select, .drawer-content textarea {
    background: rgba(255, 255, 255, 0.6) !important;
    border: 1px solid rgba(255, 255, 255, 0.7) !important;
    color: #0f172a !important;
}

/* 6. 弹出菜单与设置下拉 (Options, Popups, Modals) */
#options, #extensionsMenu, .popup .popper-modal, .options-content {
    background: rgba(255, 255, 255, 0.7) !important;
    backdrop-filter: blur(16px) !important;
    -webkit-backdrop-filter: blur(16px) !important;
    border: 1px solid rgba(255, 255, 255, 0.7) !important;
    color: #1e293b !important;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.1) !important;
}

.options-content a, .list-group-item, .options-content div {
    color: #1e293b !important;
}

.options-content a:hover, .list-group-item:hover {
    background: rgba(255, 255, 255, 0.8) !important;
    color: #0284c7 !important;
}

/* 7. 底部输入栏 (Bottom Send Form) */
#send_form {
    background: rgba(255, 255, 255, 0.38) !important;
    backdrop-filter: blur(14px) !important;
    -webkit-backdrop-filter: blur(14px) !important;
    border: 1px solid rgba(255, 255, 255, 0.65) !important;
    border-radius: 16px !important;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.05) !important;
}

#send_textarea {
    color: #0f172a !important;
    font-weight: 500 !important;
    text-shadow: 0 1px 2px rgba(255, 255, 255, 0.85) !important;
}

#send_textarea::placeholder {
    color: rgba(51, 65, 85, 0.65) !important;
}

#rightSendForm > div, #leftSendForm > div, #options_button {
    color: #1e293b !important;
    opacity: 0.85 !important;
}

#rightSendForm > div:hover, #leftSendForm > div:hover, #options_button:hover {
    color: #0284c7 !important;
    opacity: 1 !important;
}

/* 8. 思考过程框 (Reasoning Details) */
.mes_reasoning {
    background: rgba(240, 248, 255, 0.45) !important;
    border-left: 3px solid #38bdf8 !important;
    color: #334155 !important;
    backdrop-filter: blur(8px) !important;
}

